    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap" rel="stylesheet">
    <script src="https://cdnjs.cloudflare.com/ajax/libs/crypto-js/4.1.1/crypto-js.min.js"></script>
    <style>
        :root{color-scheme:dark;--bg:#090d17;--panel:rgba(20,27,44,.72);--line:rgba(255,255,255,.1);--text:#f2f5fb;--muted:#929caf;--mint:#83ecc4;--blue:#91a9ff}*{box-sizing:border-box}body{margin:0;height:100vh;overflow:hidden;background:radial-gradient(ellipse at 5% 0,rgba(79,116,255,.17),transparent 34%),radial-gradient(ellipse at 95% 100%,rgba(82,222,184,.1),transparent 34%),var(--bg);color:var(--text);font:14px 'DM Sans',sans-serif}.glass{background:linear-gradient(145deg,rgba(255,255,255,.09),rgba(255,255,255,.025));border:1px solid var(--line);backdrop-filter:blur(22px);-webkit-backdrop-filter:blur(22px);box-shadow:0 20px 70px rgba(0,0,0,.25)}.app{height:100vh;padding:18px;display:grid;grid-template-columns:300px minmax(0,1fr);gap:16px}.sidebar,.chat{min-height:0;border-radius:22px;overflow:hidden}.sidebar{display:flex;flex-direction:column}.side-head{padding:23px 20px 18px;border-bottom:1px solid var(--line)}.brand{font:700 1.18rem 'Space Grotesk',sans-serif;letter-spacing:-.04em;display:flex;align-items:center;gap:10px}.brand img{width:34px;height:34px;object-fit:contain}.brand span{color:var(--mint)}.subline{color:var(--muted);font-size:.8rem;margin:12px 0 17px}.search{width:100%;padding:11px 13px;border-radius:12px;border:1px solid var(--line);background:rgba(3,7,14,.45);color:var(--text);font:inherit;outline:none}.search:focus,.input:focus,.key-input:focus,.modal input:focus{border-color:rgba(131,236,196,.6)}.list-label{padding:17px 20px 7px;text-transform:uppercase;letter-spacing:.1em;color:#818ba0;font-size:.68rem;font-weight:700}.user-list{flex:1;overflow:auto;padding:6px 10px}.user-card{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px 11px;margin-bottom:5px;border:1px solid transparent;border-radius:14px;color:#e8ecf5;transition:.18s}.user-card:hover{background:rgba(255,255,255,.055);border-color:var(--line)}.user-card b{font-weight:600}.user-card .status-dot{width:8px;height:8px;border-radius:50%;margin-right:8px}.user-card div{min-width:0}.user-card div div{color:var(--muted)!important}.user-card span:last-child{font-size:.63rem!important;letter-spacing:.05em}.side-foot{display:flex;flex-wrap:wrap;gap:8px;padding:13px;border-top:1px solid var(--line)}.side-link{flex:1;text-align:center;padding:9px 7px;border:1px solid var(--line);border-radius:10px;color:#c7cfdf;font-size:.76rem}.side-link:hover{color:var(--mint);border-color:rgba(131,236,196,.35)}.side-link.abort{color:#ff9da7}.chat{display:flex;flex-direction:column;position:relative}.chat-head{min-height:76px;padding:14px 20px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line)}.target{font:600 1rem 'Space Grotesk',sans-serif}.target-sub{font-size:.75rem;color:var(--muted);margin-top:4px}.head-actions{display:flex;align-items:center;gap:10px}.key-wrap{display:flex;align-items:center;gap:9px;color:var(--muted);font-size:.76rem}.key-input,.input,.modal input{font:inherit;color:var(--text);background:rgba(3,7,14,.5);border:1px solid var(--line);border-radius:11px;padding:10px 12px;outline:none}.key-input{width:150px}.messages{flex:1;min-height:0;overflow:auto;padding:24px clamp(16px,5vw,60px);display:flex;flex-direction:column;gap:12px}.empty{margin:auto;text-align:center;color:var(--muted);line-height:1.8}.empty img{width:60px;height:60px;object-fit:contain;opacity:.75;margin-bottom:12px}.msg{max-width:min(70%,560px);padding:12px 15px;border-radius:17px;line-height:1.55;overflow-wrap:anywhere;white-space:pre-wrap}.msg.sent{align-self:flex-end;background:linear-gradient(135deg,rgba(131,236,196,.17),rgba(145,169,255,.13));border:1px solid rgba(131,236,196,.2);color:#edfdf6;border-bottom-right-radius:5px}.msg.received{align-self:flex-start;background:rgba(255,255,255,.065);border:1px solid var(--line);color:#e5e9f2;border-bottom-left-radius:5px}.msg-time{display:block;font-size:.65rem;color:#9ca6b8;text-align:right;margin-top:7px}.file-link{color:var(--mint);text-decoration:underline}.chat-img{display:block;max-width:100%;max-height:300px;border-radius:11px;cursor:pointer}.input-zone{display:flex;align-items:center;gap:10px;padding:15px 20px;border-top:1px solid var(--line);background:rgba(5,9,16,.22)}.attach,.send,.icon-btn{border:0;cursor:pointer;color:var(--text);font:600 .88rem 'DM Sans',sans-serif;border-radius:11px;padding:11px 14px}.attach,.icon-btn{background:rgba(255,255,255,.07);border:1px solid var(--line)}.attach:hover,.icon-btn:hover{color:var(--mint)}.input{flex:1;min-width:0}.send{background:linear-gradient(135deg,#a2f4d5,#85e6d0);color:#09120f;padding:12px 19px}.send:hover{filter:brightness(1.08)}.hidden{display:none!important}.mobile-menu{display:none}#toast{position:fixed;z-index:30;bottom:25px;left:50%;transform:translate(-50%,12px);opacity:0;padding:12px 17px;border-radius:12px;background:rgba(22,29,46,.95);border:1px solid var(--line);box-shadow:0 12px 40px #0005;transition:.2s}#toast.show{opacity:1;transform:translate(-50%,0)}#contextMenu{position:fixed;z-index:25;display:none;padding:6px;border-radius:12px;background:rgba(22,29,46,.97);border:1px solid var(--line);backdrop-filter:blur(15px)}#contextMenu div{padding:10px 14px;border-radius:8px;cursor:pointer;color:#ffb5bd;font-size:.8rem}#contextMenu div:hover{background:rgba(255,120,140,.1)}.modal-overlay{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(2,5,11,.72);backdrop-filter:blur(8px)}.modal{width:min(400px,100%);padding:25px;border-radius:20px}.modal h2{font:600 1.3rem 'Space Grotesk',sans-serif;margin:0 0 20px}.modal input{width:100%;margin:0 0 12px}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:8px}.modal-actions button{font:600 .82rem 'DM Sans',sans-serif}.hidden{display:none!important}
        @media(max-width:760px){.app{padding:0;display:block}.sidebar{position:fixed;z-index:10;inset:10px auto 10px 10px;width:min(330px,calc(100vw - 20px));display:none}.sidebar.active{display:flex}.chat{height:100vh;border:0;border-radius:0}.mobile-menu{display:inline-flex}.chat-head{padding:12px 14px}.key-wrap{gap:5px}.key-input{width:112px}.messages{padding:20px 15px}.msg{max-width:88%}.input-zone{padding:11px}.attach{padding:10px}.send{padding:11px 14px}.head-actions{gap:6px}.key-label{display:none}}@media(max-width:390px){.key-input{width:91px}.target{font-size:.9rem}.input-zone{gap:6px}}
    </style>
</head>
<body>
<div id="toast" role="status" aria-live="polite"></div>
<input type="file" id="fileInput" hidden>
<aside class="sidebar glass" id="sidebar">
    <div class="side-head"><a href="index.php" class="brand"><img src="sdpGhostlink.png" alt=""><div>Ghost<span>Link</span></div></a><p class="subline">A little space for your conversations.</p><input type="search" id="searchUser" class="search" placeholder="Search people…" autocomplete="off"></div>
    <div class="list-label">Your people</div><div id="userList" class="user-list"><div class="empty">Finding people…</div></div>
    <div class="side-foot"><a href="#" class="side-link" onclick="showProfile();return false">Profile</a><a href="index.php?page=usage" class="side-link">Guide</a><a href="index.php?page=about" class="side-link">About</a><a href="logout.php" class="side-link abort">Sign out</a></div>
</aside>
<main class="chat glass">
    <header class="chat-head"><div style="display:flex;align-items:center;gap:12px"><button class="icon-btn mobile-menu" onclick="toggleSidebar()" aria-label="Open contacts">☰</button><div><div class="target" id="chatTitle">Choose someone to chat</div><div class="target-sub" id="chatSubtitle">Your private conversation starts here</div></div></div><div class="head-actions"><label class="key-wrap"><span class="key-label">Shared key</span><input type="password" id="secretKey" class="key-input" placeholder="Enter key" title="Use the same key as your contact" autocomplete="off"></label></div></header>
    <section class="messages" id="msgBox"><div class="empty"><img src="sdpGhostlink.png" alt=""><br>Select a person to start a conversation.</div></section>
    <form class="input-zone hidden" id="inputZone"><button type="button" class="attach" id="attachButton" title="Attach a file" aria-label="Attach a file">＋</button><input type="text" id="msgInput" class="input" placeholder="Write a message…" autocomplete="off"><button type="submit" class="send">Send&nbsp; ↗</button></form>
</main>
<div id="contextMenu"><div onclick="confirmDelete()">Delete message</div></div>
<div id="profileModal" class="modal-overlay hidden"><section class="modal glass"><h2>Your profile</h2><input type="text" id="editBio" placeholder="A short bio"><input type="tel" id="editPhone" placeholder="Phone number"><div class="modal-actions"><button class="icon-btn" onclick="closeProfile()">Cancel</button><button class="send" onclick="saveProfile()">Save changes</button></div></section></div>
<audio id="notifySound" src="https://actions.google.com/sounds/v1/alarms/beep_short.ogg" preload="none"></audio>
<script>
let currentTargetId=null, refreshInterval=null, selectedMsgId=null, lastMsgCount=0;
const $=id=>document.getElementById(id);
function showToast(message){const toast=$('toast');toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3000)}
function checkResponse(text){if(text.trim()==='ACCESS DENIED'){location.href='index.php?page=login&error=Session%20Expired';return false}return true}
function toggleSidebar(){ $('sidebar').classList.toggle('active') }
async function postForm(fields){const form=new FormData();for(const [key,value] of Object.entries(fields))form.append(key,value);const response=await fetch('engine.php',{method:'POST',body:form});return response.text()}
async function fetchUsers(){try{const data=await postForm({mode:'get_users',search:$('searchUser').value});if(checkResponse(data))$('userList').innerHTML=data}catch(e){showToast('Could not load contacts. Try again.')}}
window.openChat=function(userId,username){currentTargetId=userId;$('chatTitle').textContent=username;$('chatSubtitle').textContent='Messages are encrypted in your browser';$('inputZone').classList.remove('hidden');$('sidebar').classList.remove('active');$('msgBox').innerHTML='<div class="empty">Opening your conversation…</div>';if(refreshInterval)clearInterval(refreshInterval);lastMsgCount=0;fetchMessages();refreshInterval=setInterval(fetchMessages,3000)};
async function sendMessage(){const text=$('msgInput').value,key=$('secretKey').value;if(!currentTargetId){showToast('Choose someone to chat with first.');return}if(!text.trim())return;if(!key.trim()){showToast('Add your shared key before sending.');$('secretKey').focus();return}if(typeof CryptoJS==='undefined'){showToast('Encryption could not load. Refresh and try again.');return}try{const encrypted=CryptoJS.AES.encrypt(text,key).toString();const result=await postForm({mode:'send_msg',target:currentTargetId,msg:encrypted});if(checkResponse(result)){$('msgInput').value='';await fetchMessages()}}catch(e){showToast('Message could not be sent. Please retry.')}}
async function uploadFile(){const input=$('fileInput');if(!input.files.length)return;const file=input.files[0];if(file.size>25000000){showToast('File is too large (max 25 MB).');input.value='';return}if(!$('secretKey').value.trim()){showToast('Add your shared key before sharing a file.');input.value='';return}if(!currentTargetId){showToast('Choose someone to chat with first.');input.value='';return}const messageInput=$('msgInput');messageInput.value='Uploading…';try{const form=new FormData();form.append('file',file);const response=await fetch('upload.php',{method:'POST',body:form});const path=(await response.text()).trim();if(path.startsWith('error:')){showToast(path);messageInput.value='';return}messageInput.value='FILE:'+path;await sendMessage()}catch(e){showToast('Upload failed. Please try again.');messageInput.value=''}finally{input.value=''}}
function appendMessageContent(message,text){if(text.startsWith('FILE:')){const path=text.slice(5).trim();const extension=path.split('.').pop().split('?')[0].toLowerCase();if(!/^(uploads\/)[\w./-]+$/.test(path)){message.append(document.createTextNode('Attachment unavailable'));return}if(['jpg','jpeg','png','gif'].includes(extension)){const image=document.createElement('img');image.src=path;image.alt='Shared image';image.className='chat-img';image.addEventListener('click',()=>window.open(path,'_blank','noopener'));message.append(image)}else{const link=document.createElement('a');link.href=path;link.target='_blank';link.rel='noopener noreferrer';link.className='file-link';link.textContent='↗ Download '+extension.toUpperCase()+' file';message.append(link)}return}message.textContent=text}
async function fetchMessages(){if(!currentTargetId)return;try{const html=await postForm({mode:'get_msgs',target:currentTargetId});if(!checkResponse(html))return;const temp=document.createElement('div');temp.innerHTML=html;const items=[...temp.querySelectorAll('.msg')];if(lastMsgCount>0&&items.length>lastMsgCount&&items.at(-1)?.classList.contains('received'))$('notifySound').play().catch(()=>{});lastMsgCount=items.length;const key=$('secretKey').value;const fragment=document.createDocumentFragment();for(const source of items){const msg=document.createElement('div');msg.className='msg '+(source.classList.contains('sent')?'sent':'received');msg.id=source.id;msg.addEventListener('contextmenu',event=>{event.preventDefault();if(!msg.classList.contains('sent')){showToast('You can only delete your own messages.');return}selectedMsgId=source.id.replace('msg_','');const menu=$('contextMenu');menu.style.display='block';menu.style.left=Math.min(event.clientX,innerWidth-170)+'px';menu.style.top=Math.min(event.clientY,innerHeight-60)+'px'});const encrypted=source.getAttribute('data-enc')||'';let plain='🔒 Enter your shared key';if(key.trim()){try{plain=CryptoJS.AES.decrypt(encrypted,key).toString(CryptoJS.enc.Utf8)||'Could not decrypt — check the shared key.'}catch(e){plain='Could not decrypt — check the shared key.'}}appendMessageContent(msg,plain.trim());const time=document.createElement('span');time.className='msg-time';time.textContent=source.getAttribute('data-time')||'';msg.append(time);fragment.append(msg)}const box=$('msgBox');const changed=box.childElementCount!==items.length;if(changed){box.replaceChildren(fragment);box.scrollTop=box.scrollHeight}}catch(e){showToast('Could not refresh messages.')}}
function hideMenu(){$('contextMenu').style.display='none'}window.addEventListener('click',event=>{if(!event.target.closest('#contextMenu'))hideMenu()});window.confirmDelete=async function(){if(!selectedMsgId)return;if(confirm('Delete this message?')){try{const response=await postForm({mode:'delete_msg',msg_id:selectedMsgId});if(response.includes('deleted')){ $('msg_'+selectedMsgId)?.remove();showToast('Message deleted.');lastMsgCount=Math.max(0,lastMsgCount-1)}}catch(e){showToast('Could not delete the message.')}}hideMenu()};
window.showProfile=async function(){$('profileModal').classList.remove('hidden');try{const result=await postForm({mode:'get_my_profile'});if(checkResponse(result)){const data=JSON.parse(result);$('editBio').value=data.bio||'';$('editPhone').value=data.phone||''}}catch(e){showToast('Could not load your profile.')}};window.closeProfile=()=> $('profileModal').classList.add('hidden');window.saveProfile=async function(){try{await postForm({mode:'update_profile',bio:$('editBio').value,phone:$('editPhone').value});closeProfile();showToast('Profile updated.')}catch(e){showToast('Could not save your profile.')}};
$('inputZone').addEventListener('submit',event=>{event.preventDefault();sendMessage()});$('attachButton').addEventListener('click',()=>$('fileInput').click());$('fileInput').addEventListener('change',uploadFile);$('searchUser').addEventListener('input',fetchUsers);$('secretKey').addEventListener('input',()=>{if(currentTargetId)fetchMessages()});fetchUsers();setInterval(fetchUsers,5000);
</script>
</body>
</html>
